<script>
 import { onMount } from 'svelte';
 import { page } from '$app/state';
 let room = null; let name = ''; let contribution = ''; let message = ''; let busy = false; let submitted = false;
 async function load(){const response=await fetch(`/api/songs/${page.params.token}`);const data=await response.json();if(!response.ok)throw new Error(data.message);room=data;}
 onMount(()=>{load().catch(error=>message=error.message)});
 async function action(actionName){busy=true;message='';try{const response=await fetch(`/api/songs/${page.params.token}/${actionName}`,{method:'POST'});const data=await response.json();if(!response.ok)throw new Error(data.message);if(data.url){location.href=data.url;return;}await load();}catch(error){message=error.message;}finally{busy=false;}}
 async function submit(){busy=true;message='';try{const response=await fetch(`/api/songs/${page.params.token}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,contribution})});const data=await response.json();if(!response.ok)throw new Error(data.message);submitted=true;await load();}catch(error){message=error.message;}finally{busy=false;}}
</script>
<svelte:head><title>Your group song | xmincing</title><meta name="referrer" content="no-referrer" /></svelte:head>
<section>{#if room}<p class="label">A SONG FOR {room.recipient.toUpperCase()}</p><h1>Bring your words.</h1><p>{room.names.length} of {room.capacity} contributions received · {room.mood} {room.occasion}</p><p>Contributors: {room.names.join(', ') || 'Waiting for the first contribution'}</p>{#if submitted}<p>Thanks. Your contribution has been added.</p>{:else if room.status === 'collecting' && room.names.length < room.capacity}<form onsubmit={(event)=>{event.preventDefault();submit();}}><label>Your name<input bind:value={name} required maxlength="40" /></label><label>What’s one memory, detail or wish you want in the song?<textarea bind:value={contribution} required maxlength="200" rows="5"></textarea></label><p>{contribution.length} / 200</p><button disabled={busy}>{busy ? 'Sending…' : 'Add your words'}</button></form>{:else if room.status === 'collecting'}<p>All contributions are in. The host can prepare the lyrics.</p>{/if}{#if room.lyrics}<h2>Proposed lyrics</h2><pre>{room.lyrics}</pre>{/if}{#if room.isHost && room.names.length === room.capacity && room.status === 'collecting'}<button disabled={busy} onclick={() => action('prepare')}>Prepare lyrics</button>{/if}{#if room.isHost && room.status === 'review'}<p>One payment for the group: ${room.capacity === 2 ? '3.00' : (room.capacity * 1.3).toFixed(2)} USD.</p><button disabled={busy} onclick={() => action('checkout')}>Pay for the song</button>{/if}{#if room.isHost && room.paymentStatus === 'paid' && room.generationStatus !== 'complete'}<button disabled={busy || room.generationStatus === 'running'} onclick={() => action('generate')}>{busy ? 'Creating your song…' : room.generationStatus === 'running' ? 'Generation in progress' : 'Create your song'}</button>{/if}{#if room.generationStatus === 'complete'}<p>Your song is ready.</p><a href={'/api/songs/' + page.params.token + '/download'}>Download MP3</a>{/if}<p class="small">Save this link to return. This room expires after seven days.</p>{:else if !message}<p>Opening your room…</p>{/if}{#if message}<p role="alert">{message}</p>{/if}</section>
<style>section{max-width:620px;margin:60px auto}h1{font-size:3rem;letter-spacing:-.05em}.label{font-size:.75rem;color:#d52b62;letter-spacing:.15em;font-weight:800}form,label{display:grid;gap:10px}form{gap:16px;margin-top:30px}input,textarea{width:100%;padding:14px;border:1px solid #d2c8bb;border-radius:8px;background:white;font:inherit}label{font-weight:700}button{border:0;border-radius:99px;padding:15px 22px;background:#252124;color:white;font:inherit;cursor:pointer}pre{white-space:pre-wrap;font:inherit;line-height:1.6}.small{font-size:.8rem;color:#706663;margin-top:30px}</style>
